use crate::parser::Expr;
use crate::lexer::TokenType;
use std::collections::HashMap;
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum Type{Int,Float,String,Bool,Null,Unknown}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct TypeError{pub message:String}
#[derive(Debug,Default)]pub struct TypeChecker{variables:HashMap<String,Type>,constants:HashMap<String,Type>,functions:HashMap<String,(Vec<Type>,Type)>,errors:Vec<TypeError>,return_type:Option<Type>}
impl TypeChecker{pub fn new()->Self{Self::default()}pub fn check(&mut self,p:&[Expr])->Result<(),Vec<TypeError>>{for e in p{if let Expr::FnDef{name,param_types,return_type,..}=e{let ps=param_types.iter().map(|t|t.as_deref().map(parse_type).unwrap_or(Type::Unknown)).collect();let r=return_type.as_deref().map(parse_type).unwrap_or(Type::Unknown);self.functions.insert(name.clone(),(ps,r));}}for e in p{self.check_expr(e);}if self.errors.is_empty(){Ok(())}else{Err(std::mem::take(&mut self.errors))}}fn error(&mut self,m:impl Into<String>){self.errors.push(TypeError{message:m.into()})}fn check_expr(&mut self,e:&Expr)->Type{match e{Expr::Number(_)=>Type::Int,Expr::Float(_)=>Type::Float,Expr::String(_)=>Type::String,Expr::Bool(_)=>Type::Bool,Expr::Null=>Type::Null,Expr::Identifier(n)=>self.variables.get(n).or_else(||self.constants.get(n)).copied().unwrap_or_else(||{self.error(format!("undefined variable: {n}"));Type::Unknown}),Expr::Let{name,value,is_const,..}=>{let t=self.check_expr(value);if *is_const{self.constants.insert(name.clone(),t);}else{self.variables.insert(name.clone(),t)}t},Expr::Print{expr}=>{self.check_expr(expr);Type::Unknown},Expr::If{condition,then_branch,else_branch}=>{let t=self.check_expr(condition);if t!=Type::Bool&&t!=Type::Unknown{self.error("if condition must be boolean")}for s in then_branch{self.check_expr(s)}if let Some(b)=else_branch{for s in b{self.check_expr(s)}}Type::Unknown},Expr::Repeat{times,body}=>{let t=self.check_expr(times);if t!=Type::Int&&t!=Type::Unknown{self.error("repeat count must be an integer")}for s in body{self.check_expr(s)}Type::Unknown},Expr::Binary{left,op,right}=>{let l=self.check_expr(left);let r=self.check_expr(right);self.check_binary(l,op,r)},Expr::FnDef{param_types,return_type,body,..}=>{let previous=self.return_type;self.return_type=return_type.as_deref().map(parse_type);for (i,t) in param_types.iter().enumerate(){self.variables.insert(format!("$param{i}"),t.as_deref().map(parse_type).unwrap_or(Type::Unknown));}for s in body{self.check_expr(s)}self.return_type=previous;Type::Unknown},Expr::Call{name,args}=>{let ts:Vec<_>=args.iter().map(|a|self.check_expr(a)).collect();if let Some((ps,r))=self.functions.get(name).cloned(){if ps.len()!=ts.len(){self.error(format!("function {name} expects {} arguments, got {}",ps.len(),ts.len()))}else{for (i,(expected,actual)) in ps.iter().zip(ts.iter()).enumerate(){if *expected!=Type::Unknown&&*actual!=Type::Unknown&&*expected!=*actual{self.error(format!("argument {} of {name} expects {:?}, got {:?}",i+1,expected,actual));}}}r}else{self.error(format!("undefined function: {name}"));Type::Unknown}},Expr::Return{value}=>{let actual=value.as_deref().map(|v|self.check_expr(v)).unwrap_or(Type::Null);if let Some(expected)=self.return_type{if expected!=Type::Unknown&&actual!=Type::Unknown&&expected!=actual{self.error(format!("return type mismatch: expected {:?}, got {:?}",expected,actual));}}actual},Expr::NetworkScan{subnet}=>{self.check_expr(subnet);Type::Unknown},Expr::Import{..}=>Type::Unknown,Expr::Export{item}=>self.check_expr(item)}}fn check_binary(&mut self,l:Type,op:&TokenType,r:Type)->Type{use TokenType::*;match op{Plus|Minus|Star|Slash=>{let n=matches!((l,r),(Type::Int,Type::Int)|(Type::Int,Type::Float)|(Type::Float,Type::Int)|(Type::Float,Type::Float));if !n&&l!=Type::Unknown&&r!=Type::Unknown{self.error("arithmetic operands must be numeric");Type::Unknown}else if l==Type::Float||r==Type::Float{Type::Float}else{Type::Int}},EqualEqual|NotEqual|Greater|Less|GreaterEqual|LessEqual=>Type::Bool,_=>Type::Unknown}}pub fn variables(&self)->&HashMap<String,Type>{&self.variables}}
fn parse_type(s:&str)->Type{match s{"int"=>Type::Int,"float"=>Type::Float,"string"=>Type::String,"bool"=>Type::Bool,"null"=>Type::Null,_=>Type::Unknown}}
